diff --git a/.model/Spec.tla b/.model/Spec.tla
new file mode 100644
index 0000000..86c9014
--- /dev/null
+++ b/.model/Spec.tla
@@ -0,0 +1,19 @@
+---- MODULE Spec ----
+EXTENDS FiniteSets, Naturals
+CONSTANTS Pods, None
+VARIABLES lease, pc, sawFree
+\* pc: idle -> read -> exporting -> done
+Init == lease = None /\ pc = [p \in Pods |-> "idle"] /\ sawFree = [p \in Pods |-> FALSE]
+\* lease.ts:4 store.get
+Read(p) == pc[p]="idle" /\ pc'=[pc EXCEPT ![p]="read"] /\ sawFree'=[sawFree EXCEPT ![p]=(lease=None)] /\ UNCHANGED lease
+\* lease.ts:5 returns false -> worker.ts:5 skipped
+Skip(p) == pc[p]="read" /\ ~sawFree[p] /\ pc'=[pc EXCEPT ![p]="done"] /\ UNCHANGED <<lease,sawFree>>
+\* lease.ts:6 store.set (unconditional, separate round trip from the get)
+Set(p) == pc[p]="read" /\ sawFree[p] /\ lease'=p /\ pc'=[pc EXCEPT ![p]="exporting"] /\ UNCHANGED sawFree
+\* worker.ts:7-9 export finishes, finally deletes the key
+Finish(p) == pc[p]="exporting" /\ lease'=None /\ pc'=[pc EXCEPT ![p]="done"] /\ UNCHANGED sawFree
+Next == (\E p \in Pods : Read(p) \/ Skip(p) \/ Set(p) \/ Finish(p)) \/ (\A p \in Pods : pc[p]="done" /\ UNCHANGED <<lease,pc,sawFree>>)
+Spec == Init /\ [][Next]_<<lease,pc,sawFree>>
+TypeOK == lease \in Pods \cup {None} /\ pc \in [Pods -> {"idle","read","exporting","done"}]
+AtMostOneExporting == Cardinality({p \in Pods : pc[p]="exporting"}) <= 1
+====
