diff --git a/.model/labels.json b/.model/labels.json
new file mode 100644
index 0000000..d168485
--- /dev/null
+++ b/.model/labels.json
@@ -0,0 +1,17 @@
+{
+  "states": [
+    {"when": {"pc": "(a :> \"idle\" @@ b :> \"idle\")"}, "label": "Lease free, neither pod has started"},
+    {"when": {"pc": "(a :> \"read\" @@ b :> \"idle\")"}, "label": "Pod A saw the lease free, pod B not started"},
+    {"when": {"pc": "(a :> \"read\" @@ b :> \"read\")", "lease": "none"}, "label": "Both pods saw the lease free, none written yet"},
+    {"when": {"pc": "(a :> \"exporting\" @@ b :> \"read\")"}, "label": "Pod A exporting, pod B still thinks the lease is free"},
+    {"when": {"pc": "(a :> \"exporting\" @@ b :> \"exporting\")"}, "label": "BOTH pods exporting"}
+  ],
+  "show": ["pc", "lease"],
+  "actions": {
+    "Read": "a pod checks Redis for the lease and sees it free",
+    "Set": "a pod writes its lease, without checking again",
+    "Skip": "a pod sees a live lease and skips",
+    "Finish": "a pod finishes and deletes the lease"
+  },
+  "rules": {"AtMostOneExporting": "only one pod may export at a time"}
+}
